"""Editorial identity and the intentionally simple email submission route."""
from html import escape as e
from urllib.parse import quote

EMAIL = 'nalar.hakim77@gmail.com'
FORMATS = {
    'telaah': ('Telaah', 'Menempatkan fenomena aktual di hadapan hukum, teori, dan keberatan yang patut didengar.'),
    'bedah': ('Bedah Putusan & Norma', 'Menguji alasan, asumsi, serta akibat dari putusan dan aturan yang konkret.'),
    'esai': ('Esai Pemikiran', 'Mengembangkan gagasan dan menguji batas teori melalui persoalan hukum yang nyata.'),
    'perdebatan': ('Perdebatan', 'Sanggahan dan jawaban yang mempertemukan argumen, termasuk kritik terhadap tulisan kami.'),
}
MAILTO = 'mailto:' + EMAIL + '?subject=' + quote('Naskah Nalar Hakim — Judul tulisan')


def invitation(prefix=''):
    return f'''<section class="editorial-invitation" aria-labelledby="undangan-naskah"><div><span class="eyebrow">TERBUKA UNTUK KONTRIBUTOR</span><h2 id="undangan-naskah">Ada argumen yang<br>perlu dibaca?</h2><p>Kirim naskah Word melalui email baru. Lazarus meninjau setiap naskah; keputusan dan penyuntingan dikabarkan lewat email.</p></div><a class="editorial-button" href="{prefix}kirim-naskah.html">Kirim naskah <span aria-hidden="true">↗</span></a></section>'''


def form_links(prefix=''):
    rows = ''.join(f'<a class="format-card" href="{prefix}bentuk/{slug}/"><span class="eyebrow">0{index}</span><h3>{e(label)}</h3><p>{e(description)}</p><span class="format-arrow" aria-hidden="true">↗</span></a>' for index,(slug,(label,description)) in enumerate(FORMATS.items(),1))
    return '<section class="formats-section"><div class="section-heading"><h2>Empat cara menguji</h2><span class="eyebrow">BENTUK TULISAN</span></div><div class="formats-grid">'+rows+'</div></section>'


def about_page():
    return '''<main id="main-content" class="container"><article class="article-layout"><header class="article-header"><span class="eyebrow">ARAH NALAR HAKIM</span><h1>Identitas disamarkan.<br>Argumen diperiksa.</h1><p class="article-deck">Ruang kritik hukum independen. Fenomena aktual dibaca sampai ke asumsi, pertimbangan, dan akibatnya.</p></header><div class="article-content"><p>Nalar Hakim mempertemukan peristiwa dengan pemikiran hukum. Kami menerbitkan tulisan yang mempertanyakan cara hukum dibentuk, ditafsirkan, dijalankan, dan dialami. Setiap tulisan berangkat dari persoalan yang jelas dan membawa argumen yang terbuka untuk diuji.</p><h2>Kritik sampai ke dasarnya</h2><p>Sebuah aturan dapat tampak netral sambil membagikan beban secara tidak setara. Sebuah prosedur dapat dipenuhi sementara persoalan dasarnya belum terjawab. Kami menelusuri jarak itu melalui dokumen, fakta, serta teori yang membantu melihat apa yang luput dari pembacaan pertama.</p><p>Teori digunakan untuk bekerja: menjelaskan hubungan, menguji alasan, dan memperlihatkan batas suatu kesimpulan. Nama besar pemikir bukan pengganti argumentasi. Teori itu sendiri juga terbuka untuk dikritik.</p><h2>Bebas mengajukan, bersedia diuji</h2><p>Siapa pun dapat mengirimkan karya tanpa syarat gelar atau afiliasi. Naskah dinilai melalui objek pembahasan, ketelitian sumber, kekuatan tesis, dan kesanggupan menghadapi sanggahan. Perbedaan pendapat dengan Lazarus tidak menjadi alasan penolakan dengan sendirinya.</p><p>Telaah, Bedah Putusan &amp; Norma, Esai Pemikiran, dan Perdebatan menjadi empat bentuk publikasi. Bidang pidana, perdata, agama dan keluarga, filsafat hukum, serta hukum dan teknologi membantu pembaca menelusuri persoalan yang sering kali saling berhubungan.</p><h2>Penulis memakai nama samaran</h2><p>Kontributor dapat memilih nama samaran atau menerbitkan tulisan sebagai Anonim. Nama asli, gelar, dan tempat bekerja tidak menjadi syarat kiriman. Lazarus adalah nama samaran pengelola sekaligus penyunting; karya kontributor tetap memperoleh atribusinya sendiri.</p><p>Identitas yang diterima melalui komunikasi tidak dicantumkan dalam publikasi. Pengiriman saat ini berlangsung melalui email biasa. Penggunaan email baru membantu memisahkan korespondensi, tetapi tidak menjamin anonimitas teknis.</p><h2>Redaksi yang bisa dikritik</h2><p>Keputusan penerbitan berada pada Lazarus. Naskah yang layak akan diterbitkan. Naskah yang potensial akan disunting. Naskah yang jauh dari arah redaksi ditolak. Hasil peninjauan dikabarkan lewat email pengirim.</p><p>Kesalahan faktual dapat dikoreksi; perbedaan penafsiran dapat dijawab. Kami membuka ruang tanggapan atas tulisan yang terbit, termasuk tulisan Lazarus. Sumber dan riwayat perubahan membantu pembaca menilai argumen dari waktu ke waktu.</p><h2>Terbuka untuk dibaca</h2><p>Seluruh tulisan dapat dibaca tanpa akun atau biaya langganan. Dukungan sukarela membantu keberlangsungan ruang ini dan tidak memberikan kendali atas keputusan redaksi.</p><div class="inline-actions"><a class="read-link" href="kirim-naskah.html">Panduan kiriman</a><a class="read-link" href="kebijakan-redaksi.html">Kebijakan Lazarus</a></div></div></article>'''+invitation()+'</main>'


def submission_page():
    return f'''<main id="main-content" class="container submission-main"><header class="archive-header"><span class="eyebrow">KIRIM NASKAH / TANPA AKUN</span><h1>Argumen Anda.<br>Ruang bersama.</h1><p class="section-intro">Kirim karya dalam format Word. Gunakan email baru dan nama samaran. Lazarus akan membaca serta meninjau naskahnya.</p></header><div class="submission-layout"><section aria-labelledby="langkah-kiriman"><h2 id="langkah-kiriman" class="submission-heading">Empat langkah. Lewat email.</h2><ol class="submission-steps"><li><span class="step-number" aria-hidden="true">01</span><div><h3>Buat alamat email baru</h3><p>Gunakan alamat yang tidak menampilkan nama asli. Simpan aksesnya karena hasil peninjauan dan pembicaraan revisi dikirim ke alamat tersebut.</p></div></li><li><span class="step-number" aria-hidden="true">02</span><div><h3>Siapkan naskah Word</h3><p>Lampirkan file <strong>.docx atau .doc</strong> yang berisi judul, nama samaran atau “Anonim”, isi tulisan, dan sumber rujukan. Tidak perlu CV, gelar, atau format jurnal tertentu.</p><p>Berangkatlah dari fenomena, putusan, atau aturan yang konkret. Jelaskan tesis, gunakan teori untuk menguji persoalan, dan hadapi argumen yang berlawanan.</p></div></li><li><span class="step-number" aria-hidden="true">03</span><div><h3>Kirim ke email redaksi</h3><p>Gunakan subjek <strong>Naskah Nalar Hakim — Judul tulisan</strong>. Sertakan file Word sebagai lampiran dan pernyataan bahwa karya tersebut milik Anda serta diajukan untuk diterbitkan.</p></div></li><li><span class="step-number" aria-hidden="true">04</span><div><h3>Tunggu kabar dari Lazarus</h3><p>Naskah ditinjau terlebih dahulu. Keputusan terbit, penyuntingan, atau penolakan disampaikan melalui email. Pantau kotak masuk dan folder spam.</p></div></li></ol></section><aside class="submission-contact" aria-labelledby="alamat-redaksi"><span class="eyebrow">ALAMAT PENGIRIMAN</span><h2 id="alamat-redaksi">Meja Lazarus.</h2><a class="submission-email" href="mailto:{EMAIL}">{EMAIL}</a><div class="submission-actions"><a class="editorial-button" href="{MAILTO}">Tulis email pengiriman <span aria-hidden="true">↗</span></a><button type="button" class="editorial-button secondary" data-copy-email="{EMAIL}" hidden>Salin alamat email</button></div><p data-email-status role="status" aria-live="polite"></p><p class="submission-hint">Tombol membuka aplikasi email. Gunakan akun email baru dan lampirkan naskah Word sebelum mengirim. Alamat di atas juga dapat disalin ke layanan email Anda.</p><div class="privacy-note"><h3>Nama samaran, dengan batas yang jelas.</h3><p>Nama asli tidak diperlukan untuk publikasi. Email baru tidak menjamin anonimitas; periksa nama pembuat dan komentar di berkas Word sebelum mengirim.</p></div></aside></div><section class="review-section" aria-labelledby="hasil-tinjauan"><div class="section-heading"><h2 id="hasil-tinjauan">Setelah dibaca</h2><a href="kebijakan-redaksi.html">Kebijakan Lazarus ↗</a></div><div class="review-grid"><article><span class="eyebrow">01 / LAYAK</span><h3>Diterbitkan.</h3><p>Argumen, sumber, dan arah tulisan memenuhi pertimbangan redaksi. Naskah disiapkan untuk terbit dengan nama samaran.</p></article><article><span class="eyebrow">02 / POTENSIAL</span><h3>Disunting.</h3><p>Gagasan dapat dikembangkan. Lazarus menyampaikan perubahan atau kebutuhan revisi melalui email; perubahan substansi dikomunikasikan sebelum terbit.</p></article><article><span class="eyebrow">03 / TIDAK SESUAI</span><h3>Tidak diterbitkan.</h3><p>Naskah yang jauh dari arah atau standar redaksi ditolak. Keputusannya diberitahukan lewat email.</p></article></div></section><section class="reply-note"><h2>Ingin menyanggah sebuah tulisan?</h2><p>Gunakan alur yang sama. Cantumkan judul atau tautan artikel yang ditanggapi, bagian yang dipersoalkan, dan dasar argumen Anda. Sanggahan ditinjau untuk ruang <a href="bentuk/perdebatan/">Perdebatan</a>.</p></section></main>'''


def policy_page():
    return f'''<main id="main-content" class="container"><article class="article-layout"><header class="article-header"><span class="eyebrow">KEBIJAKAN REDAKSI / LAZARUS</span><h1>Terbuka pada suara.<br>Teliti pada alasan.</h1><p class="article-deck">Naskah diterbitkan melalui peninjauan Lazarus. Inilah pertimbangan yang digunakan dalam membaca, menyunting, dan memutuskan kiriman.</p></header><div class="article-content"><h2>Arah tulisan</h2><p>Nalar Hakim memuat kritik atas fenomena hukum aktual, putusan, norma, dan pemikiran yang memengaruhi kehidupan bersama. Sebuah naskah perlu memiliki objek yang jelas, tesis yang dapat diuji, serta kontribusi pemikiran. Uraian definisi atau rangkuman umum saja belum cukup.</p><h2>Teori dan sumber</h2><p>Teori harus membantu analisis dan dapat diuji batasnya. Klaim tentang fakta dan isi dokumen memerlukan sumber yang dapat diperiksa. Utamakan teks aturan, putusan, dokumen resmi, serta karya pemikir yang benar-benar digunakan. Bedakan fakta, penafsiran, dugaan, dan penilaian.</p><p>Penulis bebas memilih format rujukan yang jelas. Redaksi dapat merapikan penyajiannya. Kutipan perlu akurat dan atribusi harus diberikan; karya hasil penjiplakan atau sumber yang direkayasa tidak diterbitkan.</p><h2>Keputusan Lazarus</h2><p>Naskah yang layak disiapkan untuk terbit. Naskah yang potensial disunting atau dikembalikan dengan kebutuhan revisi. Naskah yang jauh dari arah dan standar redaksi ditolak. Keputusan dan pembicaraan penyuntingan dikirim melalui email pengirim.</p><p>Penyuntingan dapat memperjelas struktur, bahasa, sumber, dan penalaran. Perubahan yang memengaruhi substansi dikomunikasikan kepada penulis sebelum diterbitkan. Pengiriman naskah tidak berarti jaminan terbit.</p><h2>Nama samaran dan korespondensi</h2><p>Karya terbit dengan nama samaran yang dipilih kontributor atau sebagai Anonim. Nama asli, afiliasi, dan gelar tidak diwajibkan. Identitas pribadi yang diketahui dalam korespondensi tidak dimasukkan ke publikasi.</p><p>Peninjauan menggunakan email biasa. Alamat baru membantu memisahkan korespondensi, tetapi tidak menjamin anonimitas teknis. Periksa metadata dan komentar dalam dokumen serta detail cerita yang dapat mengungkap identitas sebelum mengirim.</p><h2>Kebebasan berpendapat</h2><p>Kesimpulan tidak harus sejalan dengan Lazarus. Kritik dapat diarahkan pada lembaga, kebijakan, putusan, teori, atau tulisan Nalar Hakim sendiri. Kekuatan argumen dan bukti menjadi dasar penilaian; serangan pribadi, pembukaan identitas pihak lain, dan tuduhan tanpa dukungan memadai tidak diterbitkan.</p><p>Penulis perlu memberi tahu redaksi bila memiliki keterlibatan atau kepentingan langsung yang relevan dengan pokok tulisan. Informasi yang diperlukan agar pembaca memahami posisi tulisan dapat disajikan tanpa mencantumkan identitas pribadi.</p><h2>Koreksi dan tanggapan</h2><p>Kirim judul tulisan, bagian yang dipersoalkan, dan sumber pembanding ke <a href="mailto:{EMAIL}">{EMAIL}</a>. Kekeliruan faktual diperiksa dan koreksi substantif dicatat pada artikel. Perbedaan penafsiran dapat dikembangkan menjadi sanggahan dalam ruang Perdebatan.</p><p>Lazarus berwenang menarik tulisan bila ditemukan masalah mendasar pada sumber atau keasliannya. Penarikan disertai penjelasan editorial yang menjaga informasi pribadi penulis.</p><h2>Dukungan dan independensi</h2><p>Pengiriman naskah dan akses membaca tidak dipungut biaya. Donasi tidak memberikan hak untuk menentukan tulisan yang terbit atau mengubah kesimpulan penulis.</p><a class="read-link" href="kirim-naskah.html">Kirim karya Anda</a></div></article></main>'''
